<?php namespace AISEO\AI\Providers; use AISEO\AI\AI_Provider; class OpenAI extends AI_Provider { public function get_name():string{return'OpenAI';} public function generate(string $p,array $o):array{ $key=get_option('ai_seo_openai_key',''); $url='https://api.openai.com/v1/chat/completions'; $data=['model'=>$o['model']??'gpt-4o','messages'=>[['role'=>'user','content'=>$p]],'temperature'=>($o['temp']??0.7)]; $res=wp_remote_post($url,['headers'=>['Authorization'=>'Bearer '.sanitize_text_field($key),'Content-Type'=>'application/json'],'body'=>wp_json_encode($data),'timeout'=>60]); return ['content'=>wp_remote_retrieve_body($res),'provider'=>'openai']; } }
